-- ============================================================
-- 伏見の清酒（テーマID: 24, category_id: 3）問題投入SQL
-- 全20問（難易度1〜3）
-- 選択肢対応: (ア)=0, (イ)=1, (ウ)=2, (エ)=3
-- ============================================================

INSERT INTO questions (category_id, theme_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty_level, is_premium) VALUES

(3, 24, '伏見が清酒の名産地として全国に知られる理由として最も重要なのはどれか。', '山に囲まれた閉鎖的な地形', '豊富で良質な地下水（伏流水）', '温暖な気候', '豊臣秀吉の特許', 1, '伏見が清酒の産地として発展した最大の理由は豊富で良質な地下水（伏流水）です。醍醐山系・伏見桃山の地下に蓄えられた軟水が酒造りに最適で、日本酒の名産地「灘（硬水）」と対比される代表的な軟水産地です。', 1, false),
(3, 24, '伏見の清酒の水として知られる「御香宮神社（ごこうのみやじんじゃ）」の湧水の名前はどれか。', '走井水', '御香水', '伏見の名水', '桃山の清水', 1, '御香宮神社には「御香水（ごこうすい）」と呼ばれる名水が湧き出ており、伏見の酒造りに使われてきた水として知られています。この水が清酒の品質を支えており、現在も境内で汲むことができます。', 1, false),
(3, 24, '伏見を代表する日本酒ブランド「月桂冠（げっけいかん）」の創業年として正しいのはどれか。', '1637年（江戸初期）', '1637年（寛永14年）', '1751年（宝暦元年）', '1868年（明治元年）', 0, '月桂冠は1637年（寛永14年）に大倉治右衛門が創業した老舗酒造です。「月桂冠」というブランド名は1905年（明治38年）に命名されました。大倉記念館として酒造りの歴史を紹介する施設も公開されています。', 2, false),
(3, 24, '伏見の酒の特徴として「灘（なだ）の酒」と比べた場合の説明として正しいのはどれか。', '伏見は硬水・灘は軟水', '伏見は軟水で口当たりが柔らかく「女酒」・灘は硬水で辛口の「男酒」', '伏見と灘は同じ水質', '灘の方が歴史が古い', 1, '伏見の水は軟水で、まろやかで口当たりの柔らかい「女酒（おんなざけ）」と呼ばれる酒ができます。一方、灘（兵庫）の水は硬水（宮水）で、辛口でキレのある「男酒（おとこざけ）」が生まれます。', 1, false),
(3, 24, '「黄桜（きざくら）」として知られる伏見の酒造メーカーが運営するカッパの博物館・資料館はどれか。', '黄桜資料館', 'キザクラカッパカントリー', '黄桜酒蔵ミュージアム', 'KIZAKURA MUSEUM', 1, '黄桜（きざくら）は「キザクラカッパカントリー」として知られる施設を伏見に持ちます。カッパのキャラクターで有名な黄桜の歴史・酒造りを紹介する体験施設で、酒蔵レストランも併設されています。', 2, false),
(3, 24, '伏見の酒蔵が集中している地区として有名なのはどれか。', '宇治橋付近', '桃山御陵付近', '御香宮・宮本町周辺（酒蔵街）', '藤森神社周辺', 2, '伏見の酒蔵は伏見桃山周辺・御香宮神社周辺の宮本町・中書島地区に集中しており、白壁の酒蔵が立ち並ぶ「酒蔵街（さかぐらがい）」として観光地にもなっています。', 1, false),
(3, 24, '江戸時代に伏見の酒を大量輸送した水路として使われたものはどれか。', '琵琶湖疏水', '濠川（ごうかわ）・宇治川', '鴨川', '疏水分線', 1, '伏見の酒は江戸時代、濠川（ごうかわ）・宇治川などの水路を使って大阪・江戸へ輸送されました。「三十石船（さんじっこくぶね）」と呼ばれる船が酒樽を積んで頻繁に往来し、伏見は水運の要衝でもありました。', 2, false),
(3, 24, '日本酒の「純米大吟醸（じゅんまいだいぎんじょう）」の説明として正しいのはどれか。', '精米歩合60%以上の米と醸造アルコールを使用', '精米歩合50%以下の米のみで作り醸造アルコールを使わない', '麦を主原料にした日本酒', '精米歩合90%以上の米で作る大量生産品', 1, '純米大吟醸は精米歩合50%以下（米の外側を50%以上削った白米）のみで作り、醸造アルコールを添加しない最高グレードの日本酒です。フルーティな香りと繊細な味わいが特徴です。', 2, false),
(3, 24, '伏見の酒蔵の建物に多く見られる「なまこ壁（かべ）」の特徴はどれか。', '竹で組んだ壁', '平たい瓦を張り目地を漆喰で盛り上げた壁', '石垣を模した壁', '漆を塗った黒い壁', 1, '「なまこ壁（海鼠壁）」は平たい瓦を格子状に張り、その目地（継ぎ目）を半円形に盛り上げた漆喰で仕上げた伝統的な壁面です。防火・防湿に優れており、伏見の酒蔵や全国の蔵建築でよく見られます。', 2, false),
(3, 24, '「寺田屋（てらだや）」事件が起きた場所として伏見で有名な旅籠はどれか。', '角屋', '宝や', '寺田屋', '薩摩屋', 2, '寺田屋（てらだや）は伏見に実在する旅籠（船宿）で、1862年の「寺田屋事件」（薩摩藩の内紛）と1866年の坂本龍馬が襲撃を受けた事件（寺田屋事件）の舞台として有名です。現在も旅館として営業しています。', 1, false),
(3, 24, '「月の桂（つきのかつら）」として知られる増田徳兵衛商店が伏見で古くから醸造している特殊な酒はどれか。', 'ウイスキー', '梅酒', '濁酒（どぶろく）・にごり酒', 'ビール', 2, '増田徳兵衛商店（月の桂）は伏見の老舗酒蔵で、にごり酒・活性にごり酒の醸造で特に有名です。清酒本来の風味を残したにごり酒の復活・普及に貢献し、現在も人気の銘柄として知られています。', 2, false),
(3, 24, '「日本三大酒どころ」として知られる産地の組み合わせとして正しいのはどれか。', '伏見・灘・西条（広島）', '伏見・灘・沖縄', '伏見・灘・博多', '京都・大阪・東京', 0, '日本三大酒どころは「伏見（京都）・灘（兵庫）・西条（広島）」です。それぞれ異なる水質・気候・技術を持つ産地として知られており、日本酒の多様な味わいを代表しています。', 2, false),
(3, 24, '伏見の酒造りで「寒造り（かんづくり）」が行われる時期はいつか。', '4〜6月（春）', '10〜3月（冬）', '7〜9月（夏）', '通年', 1, '寒造り（かんづくり）は冬（10〜3月頃）の寒い時期に行う清酒の醸造です。低温で雑菌の繁殖を抑えながら発酵させることで、品質の高い清酒が醸造できます。現代でも伝統的な清酒製造の中心は冬季に行われます。', 1, false),
(3, 24, '清酒の醸造工程で「麹（こうじ）」の役割として正しいのはどれか。', '発酵を停止させる', '米のでんぷんを糖に分解する', '酒に色をつける', '香りをつける', 1, '麹（Aspergillus oryzae）は米のでんぷんを糖（ブドウ糖）に分解する酵素（アミラーゼ）を生成します。この糖を酵母がアルコールに変えて発酵が進みます。「並行複発酵（へいこうふくはっこう）」という清酒特有のプロセスです。', 2, false),
(3, 24, '伏見の「中書島（ちゅうしょじま）」地区が酒蔵の集積地として発展した理由として最も重要なのはどれか。', '豊臣秀吉の城下町', '水路網（濠川・宇治川）による輸送の利便性', '鉄道の起点だったから', '農地が広く原材料が豊富だったから', 1, '中書島（ちゅうしょじま）は濠川・宇治川・巨椋池に接した水運の要衝で、大阪・江戸への酒樽輸送に最適な立地でした。三十石船が行き来し、伏見の酒を全国に運ぶ物流拠点として発展しました。', 2, false),
(3, 24, '「酒母（さかも・もと）」とは清酒醸造において何を指すか。', '酒を仕込む原料（米）', '優良な酵母を大量培養した発酵の元', '清酒を貯蔵するタンク', '出来上がった清酒', 1, '酒母（酒の母・もと）は清酒醸造において、健全な酵母を大量に培養した種醪（たねもろみ）のことです。酒母を使って本格的な醪（もろみ）を仕込みます。「生酛（きもと）」「速醸酛（そくじょうもと）」などの製法があります。', 3, false),
(3, 24, '伏見で江戸幕府が設けた「奉行所（ぶぎょうしょ）」の名称はどれか。', '伏見城代', '伏見奉行', '伏見代官所', '伏見藩庁', 1, '江戸幕府は伏見に「伏見奉行（ふしみぶぎょう）」を置き、伏見の行政・商業・水運を管理しました。伏見の酒蔵も奉行所の管轄下に置かれ、酒造高や販売などが管理されていました。', 3, false),
(3, 24, '伏見の清酒が「女酒（おんなざけ）」と呼ばれる理由として正しいのはどれか。', '女性だけが作る酒だから', '柔らかく甘みのある軟水仕込みの穏やかな味から', '女性向けに甘く作られているから', '女性神官に守護されているから', 1, '「女酒」は軟水で仕込む伏見の酒の味わい（まろやかで口当たりが柔らかい）を擬人化した呼び名です。「男酒」と呼ばれる灘（硬水・辛口）との対比で使われる表現で、伏見の酒の特徴を表す有名なキャッチフレーズです。', 1, false),
(3, 24, '伏見の「酒蔵ラン・船旅」など観光資源として活用される水路はどれか。', '鴨川', '濠川（ごうかわ）', '桂川', '天神川', 1, '濠川（ごうかわ）は伏見港から宇治川へつながる水路で、伏見の酒を輸送した歴史的な航路です。現在は「十石舟・三十石船」の観光遊覧船が運航しており、白壁の酒蔵を水路から見学できる観光コースとして人気です。', 1, false),
(3, 24, '豊臣秀吉が伏見城を築いたことが伏見の発展に与えた影響として正しいのはどれか。', '酒蔵が城内に移転させられた', '城下町として整備されたことで人口・商業が発展し酒需要が拡大した', '秀吉が酒を禁止した', '伏見城の堀が酒造用水として使われた', 1, '豊臣秀吉が伏見に大規模な城（伏見城）を築いたことで、城下町として急速に発展しました。大量の人口流入により酒の需要が急増し、伏見の酒造業が本格的に発展するきっかけとなりました。', 2, false);

